  ('b-yogurt-banana-oat-bowl', 'Yogurt, Banana and Oat Bowl', 'Plain yogurt with banana, strawberries and a handful of oats', 'breakfast', 'yogurt', '🍌', 5, 'quick', 368, 13, 63, 9, 8, 28, 96, '[{"name":"yogurt","amount":200,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"oats","amount":30,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the yogurt into a bowl and stir in the oats","Slice the banana and strawberries","Top the yogurt with the fruit and a pinch of cinnamon"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","yogurt","banana","oats","strawberries","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа кисело мляко с банан и овесени ядки","description":"Кисело мляко с банан, ягоди и шепа овесени ядки","instructions":["Сипете киселото мляко в купа и разбъркайте в него овесените ядки","Нарежете банана и ягодите на резенчета","Сложете плодовете върху млякото и поръсете с щипка канела"],"seasonings":["щипка канела"]},"nl":{"name":"Yoghurt met banaan en havermout","description":"Yoghurt met banaan, aardbeien en een handje havermout","instructions":["Schep de yoghurt in een kom en roer de havermout erdoor","Snijd de banaan en de aardbeien in plakjes","Leg het fruit op de yoghurt en bestrooi met een snufje kaneel"],"seasonings":["snufje kaneel"]}}'::jsonb, 25),
  ('b-cottage-cheese-tomato-toast', 'Cottage Cheese and Tomato Toast', 'Toast piled with cottage cheese, tomato and cucumber', 'breakfast', 'cottage cheese', '🍅', 5, 'quick', 350, 27, 41, 9, 6, 11, 797, '[{"name":"cottage cheese","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"}]'::jsonb, '["black pepper","pinch of salt","pinch of dried oregano"]'::jsonb, '["Toast the bread","Spread the cottage cheese over both slices","Top with the sliced tomato and cucumber and season with salt, pepper and oregano"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","cottage cheese","bread","tomato","cucumber","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка с котидж сирене и домат","description":"Препечена филийка с котидж сирене, домат и краставица","instructions":["Препечете хляба","Намажете котидж сиренето върху двете филийки","Сложете отгоре нарязаните домат и краставица и овкусете със сол, пипер и риган"],"seasonings":["черен пипер","щипка сол","щипка сух риган"]},"nl":{"name":"Toast met hüttenkäse en tomaat","description":"Toast met hüttenkäse, tomaat en komkommer","instructions":["Rooster het brood","Verdeel de hüttenkäse over beide sneetjes","Leg de plakjes tomaat en komkommer erop en bestrooi met zout, peper en oregano"],"seasonings":["zwarte peper","snufje zout","snufje gedroogde oregano"]}}'::jsonb, 26),
  ('b-fruit-salad-yogurt', 'Fruit Salad with Yogurt', 'Apple, banana and berries with plain yogurt', 'breakfast', 'yogurt', '🍓', 8, 'quick', 358, 8, 76, 6, 11, 51, 74, '[{"name":"yogurt","amount":150,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"strawberries","amount":100,"unit":"g"},{"name":"blueberries","amount":60,"unit":"g"}]'::jsonb, '["squeeze of lemon juice"]'::jsonb, '["Core and dice the apple and slice the banana and strawberries","Toss all the fruit, including the blueberries, with a squeeze of lemon juice","Serve with the yogurt spooned over"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","yogurt","apple","banana","strawberries","blueberries","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Плодова салата с кисело мляко","description":"Ябълка, банан и горски плодове с кисело мляко","instructions":["Почистете ябълката от семките и я нарежете на кубчета, а банана и ягодите на резенчета","Разбъркайте всички плодове, включително боровинките, с няколко капки лимонов сок","Поднесете с киселото мляко отгоре"],"seasonings":["няколко капки лимонов сок"]},"nl":{"name":"Fruitsalade met yoghurt","description":"Appel, banaan en bessen met yoghurt","instructions":["Verwijder het klokhuis van de appel en snijd hem in blokjes; snijd de banaan en de aardbeien in plakjes","Meng al het fruit, ook de blauwe bessen, met een kneepje citroensap","Serveer met de yoghurt erover geschept"],"seasonings":["kneepje citroensap"]}}'::jsonb, 27),
  ('b-banana-berry-porridge', 'Dairy-Free Banana Berry Porridge', 'Oats cooked in water with mashed banana, blueberries and peanut butter', 'breakfast', 'oats', '🥣', 10, 'quick', 428, 12, 79, 10, 11, 22, 48, '[{"name":"oats","amount":60,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"blueberries","amount":60,"unit":"g"},{"name":"peanut butter","amount":10,"unit":"g"}]'::jsonb, '["{300} ml water","pinch of salt","pinch of cinnamon"]'::jsonb, '["Mash half the banana and put it in a pot with the oats, water and salt","Simmer for 5 minutes, stirring, until thick and creamy","Stir in half the blueberries","Serve topped with the remaining banana, sliced, the rest of the blueberries, the peanut butter and cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","banana","blueberries","peanut butter","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Овесена каша без млечни продукти с банан и боровинки","description":"Овесени ядки, сварени във вода, с намачкан банан, боровинки и фъстъчено масло","instructions":["Намачкайте половината банан и го сложете в тенджера с овесените ядки, водата и солта","Варете на тих огън 5 минути, като бъркате, докато кашата стане гъста и кремообразна","Разбъркайте в нея половината боровинки","Поднесете с останалия банан на резенчета, останалите боровинки, фъстъченото масло и канела отгоре"],"seasonings":["{300} мл вода","щипка сол","щипка канела"]},"nl":{"name":"Zuivelvrije havermoutpap met banaan en bessen","description":"Havermout gekookt in water met geprakte banaan, blauwe bessen en pindakaas","instructions":["Prak de helft van de banaan en doe hem met de havermout, het water en het zout in een pan","Laat 5 minuten zachtjes koken en roer, tot het dik en romig is","Roer de helft van de blauwe bessen erdoor","Serveer met de rest van de banaan in plakjes, de overige blauwe bessen, de pindakaas en kaneel erop"],"seasonings":["{300} ml water","snufje zout","snufje kaneel"]}}'::jsonb, 28),
