  ('b-french-toast', 'French Toast with Strawberries', 'Egg-soaked bread fried in butter, with strawberries and honey', 'breakfast', 'eggs', '🍞', 15, 'quick', 591, 30, 64, 24, 8, 21, 738, '[{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"milk","amount":80,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Beat the eggs with the milk, cinnamon and salt in a shallow dish","Soak each slice of bread in the mixture for 20 seconds per side","Fry in the butter over medium heat for 2 to 3 minutes per side until golden","Serve topped with the sliced strawberries and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bread","eggs","milk","butter","strawberries","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пържени филийки с ягоди","description":"Хляб, потопен в яйце и изпържен в масло, с ягоди и мед","instructions":["Разбийте яйцата с млякото, канелата и солта в плитък съд","Потопете всяка филийка в сместа по 20 секунди от всяка страна","Пържете в маслото на среден огън по 2–3 минути от всяка страна до златисто","Поднесете с нарязаните ягоди и меда отгоре"],"seasonings":["1/2 ч.л. канела","щипка сол"]},"nl":{"name":"Wentelteefjes met aardbeien","description":"Brood geweekt in ei en gebakken in boter, met aardbeien en honing","instructions":["Klop de eieren los met de melk, de kaneel en het zout in een diep bord","Week elk sneetje brood 20 seconden per kant in het mengsel","Bak in de boter op middelhoog vuur 2 tot 3 minuten per kant goudbruin","Serveer met de plakjes aardbei en de honing erop"],"seasonings":["1/2 tl kaneel","snufje zout"]}}'::jsonb, 30),
  ('b-full-cooked-breakfast', 'Full Cooked Breakfast', 'Bacon, fried eggs, mushrooms and tomato with buttered toast', 'breakfast', 'eggs', '🍳', 20, 'quick', 602, 33, 37, 36, 6, 8, 891, '[{"name":"bacon","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Cook the bacon in a dry pan over medium heat for 5 to 6 minutes until crisp and move it to a plate","Fry the halved mushrooms and the halved tomato in the bacon fat for 4 minutes","Push them aside and fry the eggs for 2 to 3 minutes until the whites are set","Serve everything with the toasted, buttered bread and a little pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bacon","eggs","mushrooms","tomato","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Пълна топла закуска","description":"Бекон, яйца на очи, гъби и домат с препечен хляб с масло","instructions":["Изпържете бекона в сух тиган на среден огън за 5–6 минути, докато стане хрупкав, и го прехвърлете в чиния","Запържете разрязаните наполовина гъби и домат в мазнината от бекона за 4 минути","Избутайте ги настрани и изпържете яйцата за 2–3 минути, докато белтъкът стегне","Поднесете всичко с препечения хляб, намазан с масло, и малко пипер"],"seasonings":["черен пипер"]},"nl":{"name":"Uitgebreid warm ontbijt","description":"Spek, gebakken eieren, champignons en tomaat met beboterde toast","instructions":["Bak het spek 5 tot 6 minuten in een droge pan op middelhoog vuur knapperig en leg het op een bord","Bak de gehalveerde champignons en de gehalveerde tomaat 4 minuten in het spekvet","Schuif ze opzij en bak de eieren 2 tot 3 minuten, tot het eiwit gestold is","Serveer alles met het geroosterde, beboterde brood en een beetje peper"],"seasonings":["zwarte peper"]}}'::jsonb, 31),
  ('b-egg-ham-cheese-toastie', 'Egg, Ham and Cheese Toastie', 'Pan-toasted sandwich with a fried egg, ham and melted cheese', 'breakfast', 'eggs', '🥪', 10, 'quick', 463, 30, 32, 23, 5, 4, 1000, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Fry the egg in half the butter for 2 minutes, flip it and cook 30 seconds more","Layer the ham, egg and sliced cheese between the bread","Toast the sandwich in the remaining butter over medium heat for 2 minutes per side until golden and the cheese melts"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","bread","eggs","ham","cheese","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Тост с яйце, шунка и кашкавал","description":"Запечен в тиган сандвич с яйце на очи, шунка и разтопен кашкавал","instructions":["Изпържете яйцето в половината масло за 2 минути, обърнете го и пържете още 30 секунди","Наредете шунката, яйцето и нарязания кашкавал между филийките","Запечете сандвича в останалото масло на среден огън по 2 минути от всяка страна, докато стане златист и кашкавалът се разтопи"],"seasonings":["черен пипер"]},"nl":{"name":"Tosti met ei, ham en kaas","description":"In de pan gebakken tosti met een gebakken ei, ham en gesmolten kaas","instructions":["Bak het ei 2 minuten in de helft van de boter, keer het en bak nog 30 seconden","Leg de ham, het ei en de plakjes kaas tussen het brood","Bak de tosti in de rest van de boter op middelhoog vuur 2 minuten per kant, tot hij goudbruin is en de kaas smelt"],"seasonings":["zwarte peper"]}}'::jsonb, 32),
  ('b-salmon-scrambled-eggs-toast', 'Scrambled Eggs with Salmon on Toast', 'Soft scrambled eggs folded with flaked salmon on buttered toast', 'breakfast', 'eggs', '🐟', 12, 'quick', 515, 37, 31, 26, 4, 3, 548, '[{"name":"salmon","amount":70,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lemon juice"]'::jsonb, '["Fry the salmon in a non-stick pan over medium heat for 3 minutes per side, then break it into flakes","Melt the butter in the pan, pour in the beaten eggs and stir gently for 2 minutes until softly set","Fold in the salmon","Serve on the toasted bread with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["quick","hearty","salmon","eggs","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бъркани яйца със сьомга върху препечен хляб","description":"Меки бъркани яйца с парченца сьомга върху филийка с масло","instructions":["Изпържете сьомгата в незалепващ тиган на среден огън по 3 минути от всяка страна, след което я разделете на парченца","Разтопете маслото в тигана, изсипете разбитите яйца и бъркайте леко 2 минути, докато стегнат меко","Добавете сьомгата и разбъркайте внимателно","Поднесете върху препечения хляб с пипер и лимонов сок"],"seasonings":["черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Roerei met zalm op toast","description":"Zacht roerei met stukjes zalm op beboterde toast","instructions":["Bak de zalm 3 minuten per kant in een koekenpan met antiaanbaklaag op middelhoog vuur en trek hem dan in stukjes","Smelt de boter in de pan, giet de losgeklopte eieren erin en roer 2 minuten voorzichtig tot ze zacht gestold zijn","Schep de zalm erdoor","Serveer op het geroosterde brood met peper en citroensap"],"seasonings":["zwarte peper","kneepje citroensap"]}}'::jsonb, 33),
  ('b-banana-oat-pancakes', 'Banana Oat Pancakes', 'Blender pancakes made from oats, banana and egg, with blueberries', 'breakfast', 'oats', '🥞', 15, 'quick', 484, 17, 73, 15, 10, 25, 112, '[{"name":"oats","amount":50,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"milk","amount":60,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"},{"name":"blueberries","amount":60,"unit":"g"}]'::jsonb, '["pinch of cinnamon","pinch of salt"]'::jsonb, '["Blend the oats, banana, egg, milk, cinnamon and salt into a smooth batter and let it stand for 2 minutes","Heat the oil in a non-stick pan over medium heat","Cook small pancakes for about 2 minutes per side until golden","Serve topped with the blueberries"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","banana","eggs","milk","oil","blueberries","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Палачинки от банан и овесени ядки","description":"Палачинки в блендер от овесени ядки, банан и яйце, с боровинки","instructions":["Пасирайте овесените ядки, банана, яйцето, млякото, канелата и солта на гладко тесто и го оставете 2 минути","Загрейте олиото в незалепващ тиган на среден огън","Печете малки палачинки около 2 минути от всяка страна до златисто","Поднесете с боровинките отгоре"],"seasonings":["щипка канела","щипка сол"]},"nl":{"name":"Pannenkoekjes van banaan en havermout","description":"Pannenkoekjes uit de blender van havermout, banaan en ei, met blauwe bessen","instructions":["Pureer de havermout, de banaan, het ei, de melk, de kaneel en het zout tot een glad beslag en laat het 2 minuten staan","Verhit de olie in een koekenpan met antiaanbaklaag op middelhoog vuur","Bak kleine pannenkoekjes ongeveer 2 minuten per kant goudbruin","Serveer met de blauwe bessen erop"],"seasonings":["snufje kaneel","snufje zout"]}}'::jsonb, 34),
  ('b-cheese-tomato-omelette', 'Cheese and Tomato Omelette', 'Three-egg omelette with melted cheese and fresh tomato', 'breakfast', 'eggs', '🧀', 8, 'quick', 397, 29, 6, 28, 1, 4, 517, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Beat the eggs with salt and pepper and dice the tomato","Melt the butter in a non-stick pan over medium heat and pour in the eggs","When almost set, scatter the grated cheese and tomato over one half","Fold over and cook 1 more minute"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","cheese","tomato","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Омлет с кашкавал и домат","description":"Омлет от три яйца с разтопен кашкавал и пресен домат","instructions":["Разбийте яйцата със сол и пипер и нарежете домата на кубчета","Разтопете маслото в незалепващ тиган на среден огън и изсипете яйцата","Когато почти стегнат, поръсете настъргания кашкавал и домата върху едната половина","Сгънете и гответе още 1 минута"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Omelet met kaas en tomaat","description":"Omelet van drie eieren met gesmolten kaas en verse tomaat","instructions":["Klop de eieren los met zout en peper en snijd de tomaat in blokjes","Smelt de boter in een koekenpan met antiaanbaklaag op middelhoog vuur en giet de eieren erin","Strooi de geraspte kaas en de tomaat over één helft als het ei bijna gestold is","Klap dicht en bak nog 1 minuut"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 35),
  ('b-avocado-chickpea-smash-toast', 'Avocado and Chickpea Smash on Toast', 'Toast topped with avocado and chickpeas mashed with lemon', 'breakfast', 'chickpeas', '🥑', 8, 'quick', 529, 18, 65, 25, 20, 9, 526, '[{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","pinch of paprika"]'::jsonb, '["Toast the bread","Mash the avocado and drained chickpeas roughly with the juice of the lemon, salt and pepper","Pile onto the toast and dust with paprika"]'::jsonb, '[]'::jsonb, '["fresh","quick","avocado","chickpeas","bread","lemon","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка с намачкани авокадо и нахут","description":"Препечена филийка с авокадо и нахут, намачкани с лимон","instructions":["Препечете хляба","Намачкайте на едро авокадото и отцедения нахут със сока от лимона, сол и пипер","Сложете върху филийките и поръсете с червен пипер"],"seasonings":["сол","черен пипер","щипка червен пипер"]},"nl":{"name":"Toast met geprakte avocado en kikkererwten","description":"Toast met avocado en kikkererwten, geprakt met citroen","instructions":["Rooster het brood","Prak de avocado en de uitgelekte kikkererwten grof met het sap van de citroen, zout en peper","Schep op de toast en bestrooi met paprikapoeder"],"seasonings":["zout","zwarte peper","snufje paprikapoeder"]}}'::jsonb, 36),
  ('b-tofu-vegetable-scramble', 'Tofu and Vegetable Scramble', 'Scrambled tofu with mushrooms, spinach and tomato', 'breakfast', 'tofu', '🍄', 12, 'quick', 310, 31, 13, 19, 7, 4, 77, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","salt","black pepper"]'::jsonb, '["Slice the mushrooms and fry them in the oil for 3 minutes","Crumble in the tofu with the turmeric, salt and pepper and cook for 4 minutes","Add the diced tomato and spinach and cook until the spinach wilts"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","tofu","mushrooms","spinach","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бъркано тофу със зеленчуци","description":"Бъркано тофу с гъби, спанак и домат","instructions":["Нарежете гъбите на филийки и ги запържете в олиото за 3 минути","Натрошете тофуто, добавете куркумата, сол и пипер и гответе 4 минути","Добавете нарязания на кубчета домат и спанака и гответе, докато спанакът омекне"],"seasonings":["1/2 ч.л. куркума","сол","черен пипер"]},"nl":{"name":"Roertofu met groenten","description":"Roertofu met champignons, spinazie en tomaat","instructions":["Snijd de champignons in plakjes en bak ze 3 minuten in de olie","Verkruimel de tofu erboven, voeg de kurkuma, zout en peper toe en bak 4 minuten","Voeg de tomatenblokjes en de spinazie toe en bak tot de spinazie slinkt"],"seasonings":["1/2 tl kurkuma","zout","zwarte peper"]}}'::jsonb, 37),
  ('b-rice-porridge-cinnamon-apple', 'Creamy Rice Porridge with Cinnamon Apple', 'Rice simmered in milk until creamy, topped with apple and honey', 'breakfast', 'rice', '🍚', 35, 'balanced', 461, 14, 88, 7, 5, 43, 150, '[{"name":"rice","amount":50,"unit":"g"},{"name":"milk","amount":300,"unit":"ml"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Put the rice, milk and salt in a pot and bring to a gentle simmer","Cook on low heat for 25 to 30 minutes, stirring often, until the rice is soft and the porridge is creamy","Dice the apple and stir half of it in for the last 5 minutes","Serve topped with the remaining apple, the honey and the cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","rice","milk","apple","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Кремообразно мляко с ориз с ябълка и канела","description":"Ориз, сварен в мляко до кремообразност, с ябълка и мед","instructions":["Сложете ориза, млякото и солта в тенджера и оставете да заври леко","Варете на слаб огън 25–30 минути, като бъркате често, докато оризът омекне и кашата стане кремообразна","Нарежете ябълката на кубчета и добавете половината през последните 5 минути","Поднесете с останалата ябълка, меда и канелата отгоре"],"seasonings":["1/2 ч.л. канела","щипка сол"]},"nl":{"name":"Romige rijstepap met kaneelappel","description":"Rijst zacht gekookt in melk tot hij romig is, met appel en honing","instructions":["Doe de rijst, de melk en het zout in een pan en breng zachtjes aan de kook","Kook 25 tot 30 minuten op laag vuur en roer vaak, tot de rijst zacht en de pap romig is","Snijd de appel in blokjes en roer de helft er de laatste 5 minuten door","Serveer met de rest van de appel, de honing en de kaneel erop"],"seasonings":["1/2 tl kaneel","snufje zout"]}}'::jsonb, 38),
  ('b-feta-tomato-egg-toast', 'Feta, Tomato and Egg Toast', 'Toast with crumbled feta, tomato, olive oil and a fried egg', 'breakfast', 'eggs', '🍅', 8, 'quick', 453, 24, 37, 24, 6, 6, 972, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"feta","amount":50,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of dried oregano","black pepper"]'::jsonb, '["Toast the bread and top it with the sliced tomato and crumbled feta","Fry the egg in the olive oil for 2 to 3 minutes","Put the egg on top and finish with oregano and pepper"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","bread","feta","tomato","eggs","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка с фета, домат и яйце","description":"Препечена филийка с натрошена фета, домат, зехтин и яйце на очи","instructions":["Препечете хляба и сложете върху него нарязания домат и натрошената фета","Изпържете яйцето в зехтина за 2–3 минути","Сложете яйцето отгоре и поръсете с риган и пипер"],"seasonings":["щипка сух риган","черен пипер"]},"nl":{"name":"Toast met feta, tomaat en ei","description":"Toast met verkruimelde feta, tomaat, olijfolie en een gebakken ei","instructions":["Rooster het brood en beleg het met de plakjes tomaat en de verkruimelde feta","Bak het ei 2 tot 3 minuten in de olijfolie","Leg het ei erop en maak af met oregano en peper"],"seasonings":["snufje gedroogde oregano","zwarte peper"]}}'::jsonb, 39),
  ('b-big-breakfast-burrito', 'Big Breakfast Burrito', 'Two tortillas filled with scrambled eggs, beans, cheese and tomato', 'breakfast', 'eggs', '🌯', 12, 'quick', 761, 37, 76, 34, 8, 9, 1427, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Warm the drained kidney beans with the cumin in the oil for 1 minute","Pour in the beaten eggs, season and scramble until just set","Warm the tortillas in a dry pan","Divide the eggs and beans, grated cheese and diced tomato between them, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","tortilla","eggs","kidney beans","cheese","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Голямо бурито за закуска","description":"Две тортили с бъркани яйца, боб, кашкавал и домат","instructions":["Затоплете отцедения червен боб с кимиона в олиото за 1 минута","Изсипете разбитите яйца, овкусете и бъркайте, докато едва стегнат","Затоплете тортилите в сух тиган","Разпределете върху тях яйцата и боба, настъргания кашкавал и нарязания на кубчета домат, подгънете краищата и навийте"],"seasonings":["1/2 ч.л. смлян кимион","сол","черен пипер"]},"nl":{"name":"Grote ontbijtburrito","description":"Twee tortilla''s gevuld met roerei, bonen, kaas en tomaat","instructions":["Verwarm de uitgelekte kidneybonen 1 minuut met de komijn in de olie","Giet de losgeklopte eieren erbij, breng op smaak en roer tot ze net gestold zijn","Verwarm de tortilla''s in een droge pan","Verdeel de eieren en bonen, de geraspte kaas en de tomatenblokjes erover, vouw de zijkanten naar binnen en rol op"],"seasonings":["1/2 tl gemalen komijn","zout","zwarte peper"]}}'::jsonb, 40),
  ('b-protein-oats', 'Peanut Butter Protein Oats', 'Thick oats with Greek yogurt, peanut butter and banana', 'breakfast', 'oats', '🥣', 10, 'quick', 785, 35, 103, 29, 12, 35, 269, '[{"name":"oats","amount":80,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"greek yogurt","amount":100,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Simmer the oats with the milk and salt for 4 to 5 minutes, stirring, until thick","Take off the heat and stir in half the yogurt","Top with the rest of the yogurt, the sliced banana, the peanut butter and cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","oats","milk","greek yogurt","peanut butter","banana","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, '{"bg":{"name":"Протеинова овесена каша с фъстъчено масло","description":"Гъста овесена каша с гръцко кисело мляко, фъстъчено масло и банан","instructions":["Варете овесените ядки с млякото и солта на тих огън 4–5 минути, като бъркате, докато кашата се сгъсти","Свалете от огъня и разбъркайте в нея половината кисело мляко","Сложете отгоре останалото кисело мляко, нарязания банан, фъстъченото масло и канела"],"seasonings":["щипка сол","щипка канела"]},"nl":{"name":"Eiwitrijke havermout met pindakaas","description":"Dikke havermout met Griekse yoghurt, pindakaas en banaan","instructions":["Laat de havermout 4 tot 5 minuten zachtjes koken met de melk en het zout en roer, tot hij dik is","Haal van het vuur en roer de helft van de yoghurt erdoor","Leg de rest van de yoghurt, de plakjes banaan, de pindakaas en kaneel erop"],"seasonings":["snufje zout","snufje kaneel"]}}'::jsonb, 41),
  ('b-egg-bacon-cheese-sandwich', 'Egg, Bacon and Cheese Sandwich', 'Triple-decker toasted sandwich with fried eggs, bacon and cheese', 'breakfast', 'eggs', '🥪', 12, 'quick', 722, 40, 46, 41, 6, 6, 1212, '[{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bacon","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Fry the bacon in a dry pan over medium heat for 4 to 5 minutes until crisp and set it aside","Fry the eggs in the bacon fat for 2 minutes, flip and cook 30 seconds more","Toast the bread and butter it","Stack the sandwich with the eggs, bacon and sliced cheese between the slices and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bread","eggs","bacon","cheese","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Сандвич с яйца, бекон и кашкавал","description":"Препечен сандвич на три етажа с яйца на очи, бекон и кашкавал","instructions":["Изпържете бекона в сух тиган на среден огън за 4–5 минути, докато стане хрупкав, и го оставете настрани","Изпържете яйцата в мазнината от бекона за 2 минути, обърнете ги и пържете още 30 секунди","Препечете хляба и го намажете с масло","Подредете сандвича с яйцата, бекона и нарязания кашкавал между филийките и поръсете с пипер"],"seasonings":["черен пипер"]},"nl":{"name":"Sandwich met ei, spek en kaas","description":"Geroosterde sandwich van drie lagen met gebakken eieren, spek en kaas","instructions":["Bak het spek 4 tot 5 minuten in een droge pan op middelhoog vuur knapperig en leg het apart","Bak de eieren 2 minuten in het spekvet, keer ze en bak nog 30 seconden","Rooster het brood en besmeer het met boter","Stapel de sandwich met de eieren, het spek en de plakjes kaas tussen de sneetjes en bestrooi met peper"],"seasonings":["zwarte peper"]}}'::jsonb, 42),
  ('b-salmon-avocado-egg-toast', 'Salmon, Avocado and Egg Toast', 'Toast with avocado, flaked salmon and fried eggs', 'breakfast', 'eggs', '🥑', 15, 'quick', 724, 42, 43, 44, 14, 4, 532, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"salmon","amount":80,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Fry the salmon in a non-stick pan over medium heat for 3 minutes per side and break it into flakes","Fry the eggs in the same pan for 2 to 3 minutes","Toast the bread and spread it with the avocado mashed with lemon juice and salt","Top with the salmon and eggs and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","hearty","bread","salmon","eggs","avocado","stovetop","breakfast"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка със сьомга, авокадо и яйца","description":"Препечена филийка с авокадо, парченца сьомга и яйца на очи","instructions":["Изпържете сьомгата в незалепващ тиган на среден огън по 3 минути от всяка страна и я разделете на парченца","Изпържете яйцата в същия тиган за 2–3 минути","Препечете хляба и го намажете с авокадото, намачкано с лимонов сок и сол","Сложете отгоре сьомгата и яйцата и поръсете с пипер"],"seasonings":["сол","черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Toast met zalm, avocado en ei","description":"Toast met avocado, stukjes zalm en gebakken eieren","instructions":["Bak de zalm 3 minuten per kant in een koekenpan met antiaanbaklaag op middelhoog vuur en trek hem in stukjes","Bak de eieren 2 tot 3 minuten in dezelfde pan","Rooster het brood en besmeer het met de avocado, geprakt met citroensap en zout","Leg de zalm en de eieren erop en bestrooi met peper"],"seasonings":["zout","zwarte peper","kneepje citroensap"]}}'::jsonb, 43),
  ('b-loaded-potato-omelette', 'Loaded Potato, Ham and Cheese Omelette', 'Three-egg omelette over fried potatoes with ham and cheese', 'breakfast', 'eggs', '🍳', 20, 'quick', 685, 43, 39, 39, 5, 4, 981, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"ham","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cut the potatoes into small cubes and fry them in the oil over medium heat for 10 to 12 minutes until golden and tender","Add the ham cut into strips for 1 minute","Pour over the beaten eggs, seasoned with salt and pepper, and cook gently for 3 minutes until almost set","Scatter with the grated cheese, cover for 1 minute until it melts and fold in half"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","eggs","potatoes","cheese","ham","oil","stovetop","breakfast"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Богат омлет с картофи, шунка и кашкавал","description":"Омлет от три яйца върху пържени картофи с шунка и кашкавал","instructions":["Нарежете картофите на малки кубчета и ги пържете в олиото на среден огън 10–12 минути, докато станат златисти и меки","Добавете нарязаната на ивици шунка за 1 минута","Залейте с разбитите яйца, овкусени със сол и пипер, и гответе на слаб огън 3 минути, докато почти стегнат","Поръсете с настъргания кашкавал, покрийте за 1 минута, докато се разтопи, и сгънете наполовина"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Rijk gevulde omelet met aardappel, ham en kaas","description":"Omelet van drie eieren over gebakken aardappelen met ham en kaas","instructions":["Snijd de aardappelen in kleine blokjes en bak ze 10 tot 12 minuten in de olie op middelhoog vuur goudbruin en gaar","Voeg de ham in reepjes toe en bak 1 minuut mee","Giet de losgeklopte eieren, op smaak gebracht met zout en peper, erover en bak 3 minuten zachtjes tot ze bijna gestold zijn","Bestrooi met de geraspte kaas, dek 1 minuut af tot hij smelt en klap dubbel"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 44),
  ('b-tofu-scramble-burrito', 'Tofu Scramble Burrito', 'Two tortillas filled with spiced tofu scramble and kidney beans', 'breakfast', 'tofu', '🌯', 15, 'quick', 770, 47, 82, 31, 13, 7, 1093, '[{"name":"tofu","amount":180,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","1/2 tsp ground cumin","1/2 tsp smoked paprika","salt"]'::jsonb, '["Crumble the tofu into the hot oil with the turmeric, cumin, paprika and salt and cook for 5 minutes","Add the drained kidney beans and heat through for 2 minutes","Warm the tortillas in a dry pan","Divide the filling between them, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","tofu","tortilla","kidney beans","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бурито с бъркано тофу","description":"Две тортили с пикантно бъркано тофу и червен боб","instructions":["Натрошете тофуто в горещото олио, добавете куркумата, кимиона, червения пипер и сол и гответе 5 минути","Добавете отцедения червен боб и затоплете 2 минути","Затоплете тортилите в сух тиган","Разпределете плънката върху тях, подгънете краищата и навийте"],"seasonings":["1/2 ч.л. куркума","1/2 ч.л. смлян кимион","1/2 ч.л. пушен червен пипер","сол"]},"nl":{"name":"Burrito met roertofu","description":"Twee tortilla''s gevuld met gekruide roertofu en kidneybonen","instructions":["Verkruimel de tofu boven de hete olie, voeg de kurkuma, de komijn, het paprikapoeder en zout toe en bak 5 minuten","Voeg de uitgelekte kidneybonen toe en verwarm 2 minuten mee","Verwarm de tortilla''s in een droge pan","Verdeel de vulling erover, vouw de zijkanten naar binnen en rol op"],"seasonings":["1/2 tl kurkuma","1/2 tl gemalen komijn","1/2 tl gerookt paprikapoeder","zout"]}}'::jsonb, 45),
  ('b-peanut-butter-overnight-oats', 'Peanut Butter Banana Overnight Oats', 'Dairy-free overnight oats with coconut milk, peanut butter and banana', 'breakfast', 'oats', '🥜', 5, 'quick', 746, 21, 97, 34, 14, 19, 142, '[{"name":"oats","amount":90,"unit":"g"},{"name":"coconut milk","amount":60,"unit":"g"},{"name":"peanut butter","amount":30,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["{180} ml water","pinch of salt","pinch of cinnamon"]'::jsonb, '["Stir the oats, coconut milk, water, salt and half the peanut butter together in a jar or bowl","Cover and leave in the fridge overnight, or for at least 4 hours","Stir well, loosen with a splash of water if needed and top with the sliced banana, the remaining peanut butter and cinnamon"]'::jsonb, '[]'::jsonb, '["quick","hearty","oats","coconut milk","peanut butter","banana","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Нощни овесени ядки с фъстъчено масло и банан","description":"Нощни овесени ядки без млечни продукти с кокосово мляко, фъстъчено масло и банан","instructions":["Разбъркайте овесените ядки, кокосовото мляко, водата, солта и половината фъстъчено масло в буркан или купа","Покрийте и оставете в хладилника за една нощ или поне за 4 часа","Разбъркайте добре, разредете с малко вода при нужда и сложете отгоре нарязания банан, останалото фъстъчено масло и канела"],"seasonings":["{180} мл вода","щипка сол","щипка канела"]},"nl":{"name":"Overnight oats met pindakaas en banaan","description":"Zuivelvrije overnight oats met kokosmelk, pindakaas en banaan","instructions":["Roer de havermout, de kokosmelk, het water, het zout en de helft van de pindakaas door elkaar in een pot of kom","Dek af en zet een nacht in de koelkast, of minstens 4 uur","Roer goed door, maak zo nodig losser met een scheutje water en leg de plakjes banaan, de rest van de pindakaas en kaneel erop"],"seasonings":["{180} ml water","snufje zout","snufje kaneel"]}}'::jsonb, 46),
  ('b-greek-yogurt-power-bowl', 'Greek Yogurt Power Bowl', 'Big bowl of Greek yogurt with banana, blueberries, peanut butter and honey', 'breakfast', 'greek yogurt', '🫐', 5, 'quick', 654, 34, 73, 28, 6, 54, 214, '[{"name":"greek yogurt","amount":300,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"blueberries","amount":80,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"honey","amount":20,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the yogurt into a bowl","Slice the banana and arrange it on top with the blueberries","Add the peanut butter in small spoonfuls, drizzle with the honey and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["fresh","quick","hearty","greek yogurt","banana","blueberries","peanut butter","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Енергийна купа с гръцко кисело мляко","description":"Голяма купа гръцко кисело мляко с банан, боровинки, фъстъчено масло и мед","instructions":["Сипете киселото мляко в купа","Нарежете банана на резенчета и го наредете отгоре заедно с боровинките","Добавете фъстъченото масло на малки лъжички, полейте с меда и поръсете с канела"],"seasonings":["щипка канела"]},"nl":{"name":"Powerbowl met Griekse yoghurt","description":"Grote kom Griekse yoghurt met banaan, blauwe bessen, pindakaas en honing","instructions":["Schep de yoghurt in een kom","Snijd de banaan in plakjes en leg ze er met de blauwe bessen op","Voeg de pindakaas in kleine lepeltjes toe, besprenkel met de honing en bestrooi met kaneel"],"seasonings":["snufje kaneel"]}}'::jsonb, 47),
  ('b-cheesy-egg-quesadilla', 'Cheesy Egg and Spinach Quesadilla', 'Crisp tortillas filled with scrambled egg, spinach and melted cheese', 'breakfast', 'eggs', '🧀', 12, 'quick', 748, 37, 63, 38, 5, 6, 1513, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"cheese","amount":50,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Melt the butter in a pan, wilt the spinach for 30 seconds, then pour in the beaten eggs and scramble until just set","Cover one tortilla with half the grated cheese, the eggs and the rest of the cheese, and top with the second tortilla","Wipe out the pan and cook the quesadilla over medium heat for 2 minutes per side until crisp","Cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","tortilla","eggs","cheese","spinach","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Кесадия с яйца, кашкавал и спанак","description":"Хрупкави тортили с бъркани яйца, спанак и разтопен кашкавал","instructions":["Разтопете маслото в тиган, задушете спанака за 30 секунди, след което изсипете разбитите яйца и бъркайте, докато едва стегнат","Покрийте едната тортила с половината настърган кашкавал, яйцата и останалия кашкавал и сложете отгоре втората тортила","Избършете тигана и печете кесадията на среден огън по 2 минути от всяка страна, докато стане хрупкава","Нарежете на триъгълници"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Quesadilla met ei, kaas en spinazie","description":"Knapperige tortilla''s gevuld met roerei, spinazie en gesmolten kaas","instructions":["Smelt de boter in een pan, laat de spinazie 30 seconden slinken, giet dan de losgeklopte eieren erbij en roer tot ze net gestold zijn","Beleg één tortilla met de helft van de geraspte kaas, de eieren en de rest van de kaas en leg de tweede tortilla erop","Veeg de pan schoon en bak de quesadilla op middelhoog vuur 2 minuten per kant knapperig","Snijd in punten"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 48),
  ('b-banana-pancake-stack', 'Banana Pancake Stack', 'Thick pancakes with banana, butter and honey', 'breakfast', 'flour', '🥞', 25, 'balanced', 750, 29, 109, 23, 5, 36, 297, '[{"name":"flour","amount":80,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"milk","amount":150,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Whisk the flour, eggs, milk and salt into a smooth, thick batter and rest it for 5 minutes","Melt a little of the butter in a non-stick pan over medium heat","Cook small thick pancakes for about 2 minutes per side until golden, adding butter as needed","Stack them with the sliced banana, drizzle with the honey and dust with cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","flour","eggs","milk","butter","banana","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Кула от палачинки с банан","description":"Дебели палачинки с банан, масло и мед","instructions":["Разбийте брашното, яйцата, млякото и солта на гладко и гъсто тесто и го оставете да почине 5 минути","Разтопете малко от маслото в незалепващ тиган на среден огън","Печете малки дебели палачинки около 2 минути от всяка страна до златисто, като добавяте масло при нужда","Наредете ги една върху друга с нарязания банан, полейте с меда и поръсете с канела"],"seasonings":["щипка сол","щипка канела"]},"nl":{"name":"Stapel pannenkoeken met banaan","description":"Dikke pannenkoeken met banaan, boter en honing","instructions":["Klop de bloem, de eieren, de melk en het zout tot een glad, dik beslag en laat het 5 minuten rusten","Smelt een beetje van de boter in een koekenpan met antiaanbaklaag op middelhoog vuur","Bak kleine dikke pannenkoeken ongeveer 2 minuten per kant goudbruin en voeg zo nodig boter toe","Stapel ze met de plakjes banaan, besprenkel met de honing en bestrooi met kaneel"],"seasonings":["snufje zout","snufje kaneel"]}}'::jsonb, 49),
  ('b-tofu-bean-breakfast-plate', 'Tofu and Bean Breakfast Plate', 'Scrambled tofu with kidney beans, tomato and spinach, and a slice of toast', 'breakfast', 'tofu', '🍳', 12, 'quick', 574, 49, 48, 25, 14, 8, 463, '[{"name":"tofu","amount":200,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of turmeric","pinch of salt","black pepper"]'::jsonb, '["Heat the oil in a pan over medium heat, crumble in the tofu and fry it with the turmeric, salt and black pepper for 4 minutes","Add the drained beans and the diced tomato and cook for 3 minutes","Stir in the spinach until wilted, and toast the bread meanwhile","Serve the scramble with the toast"]'::jsonb, '["stovetop"]'::jsonb, '["quick","hearty","tofu","kidney beans","tomato","spinach","bread","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Чиния с тофу и боб за закуска","description":"Бъркано тофу с червен боб, домат и спанак и една препечена филийка","instructions":["Загрейте олиото в тиган на среден огън, натрошете тофуто и го запържете с куркумата, сол и черен пипер за 4 минути","Добавете отцедения боб и нарязания на кубчета домат и гответе 3 минути","Добавете спанака и бъркайте, докато омекне, а междувременно препечете хляба","Поднесете тофуто с препечената филийка"],"seasonings":["щипка куркума","щипка сол","черен пипер"]},"nl":{"name":"Ontbijtbord met tofu en bonen","description":"Roertofu met kidneybonen, tomaat en spinazie, en een sneetje toast","instructions":["Verhit de olie in een pan op middelhoog vuur, verkruimel de tofu erboven en bak hem 4 minuten met de kurkuma, zout en zwarte peper","Voeg de uitgelekte bonen en de tomatenblokjes toe en bak 3 minuten","Roer de spinazie erdoor tot hij geslonken is en rooster intussen het brood","Serveer de roertofu met de toast"],"seasonings":["snufje kurkuma","snufje zout","zwarte peper"]}}'::jsonb, 50),
  ('b-breakfast-egg-fried-rice', 'Breakfast Egg Fried Rice', 'Rice fried with scrambled egg, peas and soy sauce', 'breakfast', 'eggs', '🍳', 20, 'quick', 465, 22, 56, 16, 3, 3, 872, '[{"name":"rice","amount":60,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"peas","amount":50,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of white pepper"]'::jsonb, '["Cook the rice in {150} ml of salted water, covered, for 12 minutes","Heat the oil in a pan over medium-high heat, crack in the eggs and scramble them for 1 minute until just set","Add the rice and the peas and fry for 3 minutes, breaking up the rice","Stir in the soy sauce and a little white pepper and serve"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","rice","eggs","peas","soy sauce","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пържен ориз с яйца за закуска","description":"Ориз, запържен с бъркани яйца, грах и соев сос","instructions":["Сварете ориза в {150} мл подсолена вода под капак за 12 минути","Загрейте олиото в тиган на умерено силен огън, чукнете яйцата и ги бъркайте 1 минута, докато едва стегнат","Добавете ориза и граха и пържете 3 минути, като разделяте ориза","Добавете соевия сос и малко бял пипер, разбъркайте и поднесете"],"seasonings":["щипка сол","щипка бял пипер"]},"nl":{"name":"Gebakken rijst met ei als ontbijt","description":"Rijst gebakken met roerei, doperwten en sojasaus","instructions":["Kook de rijst 12 minuten met het deksel op de pan in {150} ml water met zout","Verhit de olie in een pan op middelhoog tot hoog vuur, breek de eieren erin en roer ze 1 minuut tot ze net gestold zijn","Voeg de rijst en de doperwten toe en bak 3 minuten; maak de rijst los","Roer de sojasaus en een beetje witte peper erdoor en serveer"],"seasonings":["snufje zout","snufje witte peper"]}}'::jsonb, 51),
  ('b-savoury-soy-oats-egg', 'Savoury Oats with Egg and Soy', 'Oats cooked in water with mushrooms and spinach, topped with a fried egg and soy sauce', 'breakfast', 'oats', '🥣', 12, 'quick', 343, 18, 39, 14, 7, 2, 783, '[{"name":"oats","amount":50,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Slice the mushrooms and fry them in half of the oil in a small pot over medium heat for 3 minutes","Add the oats and {250} ml of water and simmer for 4 minutes, stirring, until thick, then stir in the spinach until wilted","Fry the egg in the rest of the oil in a small pan until the white is set","Pour the oats into a bowl, lay the egg on top and drizzle with the soy sauce"]'::jsonb, '["stovetop"]'::jsonb, '["asian","comfort","quick","light","oats","eggs","mushrooms","spinach","soy sauce","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Солена овесена каша с яйце и соев сос","description":"Овесени ядки, сварени във вода с гъби и спанак, с яйце на очи и соев сос отгоре","instructions":["Нарежете гъбите на филийки и ги запържете в половината олио в малка тенджера на среден огън за 3 минути","Добавете овесените ядки и {250} мл вода и варете на тих огън 4 минути, като бъркате, докато се сгъсти, след което добавете спанака и бъркайте, докато омекне","Изпържете яйцето в останалото олио в малък тиган, докато белтъкът стегне","Изсипете кашата в купа, сложете яйцето отгоре и полейте със соевия сос"],"seasonings":[]},"nl":{"name":"Hartige havermout met ei en soja","description":"Havermout gekookt in water met champignons en spinazie, met een gebakken ei en sojasaus erop","instructions":["Snijd de champignons in plakjes en bak ze 3 minuten in de helft van de olie in een pannetje op middelhoog vuur","Voeg de havermout en {250} ml water toe en laat 4 minuten zachtjes koken, al roerend, tot het dik is; roer dan de spinazie erdoor tot hij geslonken is","Bak het ei in de rest van de olie in een kleine pan tot het eiwit gestold is","Schenk de havermout in een kom, leg het ei erop en besprenkel met de sojasaus"],"seasonings":[]}}'::jsonb, 52),
  ('b-rice-congee-egg', 'Rice Congee with Egg and Mushrooms', 'Rice simmered until soft and silky, with mushrooms, a soft egg and soy sauce', 'breakfast', 'rice', '🍚', 40, 'weekend', 281, 13, 43, 6, 1, 2, 743, '[{"name":"rice","amount":50,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"ml"}]'::jsonb, '["pinch of salt","a little grated ginger"]'::jsonb, '["Rinse the rice, put it in a pot with {500} ml of water and a pinch of salt and bring to the boil","Turn the heat down and simmer for 30 minutes, stirring now and then, until the rice has broken down into a thick porridge","Slice the mushrooms and add them for the last 5 minutes","Boil the egg for 7 minutes in a separate pot, peel and halve it","Serve the congee with the egg on top, the soy sauce and a little grated ginger"]'::jsonb, '["stovetop"]'::jsonb, '["asian","comfort","light","rice","eggs","mushrooms","soy sauce","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Оризова каша конджи с яйце и гъби","description":"Ориз, сварен до мека и копринена каша, с гъби, рохко яйце и соев сос","instructions":["Измийте ориза, сложете го в тенджера с {500} мл вода и щипка сол и оставете да заври","Намалете огъня и варете на тих огън 30 минути, като бъркате от време на време, докато оризът се разпадне на гъста каша","Нарежете гъбите на филийки и ги добавете през последните 5 минути","Сварете яйцето за 7 минути в отделна тенджера, обелете го и го разрежете наполовина","Поднесете конджито с яйцето отгоре, соевия сос и малко настърган джинджифил"],"seasonings":["щипка сол","малко настърган джинджифил"]},"nl":{"name":"Rijstcongee met ei en champignons","description":"Rijst zacht en zijdeachtig gekookt, met champignons, een zacht ei en sojasaus","instructions":["Spoel de rijst, doe hem met {500} ml water en een snufje zout in een pan en breng aan de kook","Zet het vuur lager en laat 30 minuten zachtjes koken; roer af en toe, tot de rijst uiteengevallen is tot een dikke pap","Snijd de champignons in plakjes en voeg ze de laatste 5 minuten toe","Kook het ei 7 minuten in een aparte pan, pel het en halveer het","Serveer de congee met het ei erop, de sojasaus en een beetje geraspte gember"],"seasonings":["snufje zout","een beetje geraspte gember"]}}'::jsonb, 53),
  ('b-soy-tofu-rice-bowl', 'Soy Tofu Breakfast Rice Bowl', 'Warm rice with golden tofu, wilted spinach and soy sauce', 'breakfast', 'tofu', '🍙', 20, 'quick', 466, 33, 47, 19, 6, 0, 1060, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt"]'::jsonb, '["Cook the rice in {120} ml of salted water, covered, for 12 minutes","Pat the tofu dry and cut it into cubes, then fry it in the oil over medium-high heat for 6 minutes until golden","Add the spinach and the soy sauce and toss for 1 minute until the spinach has wilted","Spoon the tofu and spinach over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","rice","spinach","soy sauce","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз с тофу и соев сос за закуска","description":"Топъл ориз със златисто тофу, задушен спанак и соев сос","instructions":["Сварете ориза в {120} мл подсолена вода под капак за 12 минути","Подсушете тофуто и го нарежете на кубчета, след което го запържете в олиото на умерено силен огън за 6 минути до златисто","Добавете спанака и соевия сос и разбъркайте за 1 минута, докато спанакът омекне","Сложете тофуто и спанака върху ориза"],"seasonings":["щипка сол"]},"nl":{"name":"Ontbijtrijstkom met sojatofu","description":"Warme rijst met goudbruine tofu, geslonken spinazie en sojasaus","instructions":["Kook de rijst 12 minuten met het deksel op de pan in {120} ml water met zout","Dep de tofu droog en snijd hem in blokjes; bak hem dan 6 minuten in de olie op middelhoog tot hoog vuur goudbruin","Voeg de spinazie en de sojasaus toe en schep 1 minuut om tot de spinazie geslonken is","Schep de tofu en de spinazie over de rijst"],"seasonings":["snufje zout"]}}'::jsonb, 54),
  ('b-caprese-toast', 'Caprese Toast', 'Toast with mozzarella, sliced tomato and olive oil', 'breakfast', 'mozzarella', '🍅', 5, 'quick', 418, 23, 35, 21, 5, 6, 615, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of salt","black pepper","pinch of dried oregano"]'::jsonb, '["Toast the bread","Slice the mozzarella and the tomato and layer them on the toast","Drizzle with the olive oil and season with salt, black pepper and a pinch of dried oregano"]'::jsonb, '[]'::jsonb, '["italian","fresh","quick","bread","mozzarella","tomato","olive oil","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка „Капрезе“","description":"Препечена филийка с моцарела, резени домат и зехтин","instructions":["Препечете хляба","Нарежете моцарелата и домата на резени и ги наредете върху филийките","Полейте със зехтина и овкусете със сол, черен пипер и щипка сух риган"],"seasonings":["щипка сол","черен пипер","щипка сух риган"]},"nl":{"name":"Toast caprese","description":"Toast met mozzarella, plakjes tomaat en olijfolie","instructions":["Rooster het brood","Snijd de mozzarella en de tomaat in plakjes en leg ze om en om op de toast","Besprenkel met de olijfolie en bestrooi met zout, zwarte peper en een snufje gedroogde oregano"],"seasonings":["snufje zout","zwarte peper","snufje gedroogde oregano"]}}'::jsonb, 55),
  ('b-zucchini-parmesan-frittata', 'Zucchini and Parmesan Frittata', 'A thick open omelette with zucchini and parmesan, with a slice of toast', 'breakfast', 'eggs', '🥒', 15, 'quick', 448, 32, 20, 26, 3, 5, 580, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Slice the zucchini thinly and fry it in the olive oil in a small pan over medium heat for 4 minutes until soft","Beat the eggs with the grated parmesan, salt and black pepper and pour them over the zucchini","Cook on low heat for 4 minutes until nearly set, then cover the pan for 2 minutes to set the top","Slide onto a plate and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","eggs","zucchini","parmesan","olive oil","bread","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Фритата с тиквичка и пармезан","description":"Дебел открит омлет с тиквичка и пармезан, с една препечена филийка","instructions":["Нарежете тиквичката на тънки кръгчета и я запържете в зехтина в малък тиган на среден огън за 4 минути, докато омекне","Разбийте яйцата с настъргания пармезан, сол и черен пипер и ги изсипете върху тиквичката","Гответе на слаб огън 4 минути, докато почти стегне, след което покрийте тигана за 2 минути, за да стегне и отгоре","Плъзнете в чиния и поднесете с препечения хляб"],"seasonings":["щипка сол","черен пипер"]},"nl":{"name":"Frittata met courgette en Parmezaan","description":"Een dikke open omelet met courgette en Parmezaanse kaas, met een sneetje toast","instructions":["Snijd de courgette in dunne plakjes en bak ze 4 minuten in de olijfolie in een kleine pan op middelhoog vuur zacht","Klop de eieren los met de geraspte Parmezaanse kaas, zout en zwarte peper en giet ze over de courgette","Bak 4 minuten op laag vuur tot het ei bijna gestold is en dek de pan dan 2 minuten af zodat de bovenkant stolt","Laat op een bord glijden en serveer met het geroosterde brood"],"seasonings":["snufje zout","zwarte peper"]}}'::jsonb, 56),
  ('b-pesto-eggs-toast', 'Pesto Eggs on Toast', 'Eggs fried in pesto, on toast with fresh tomato', 'breakfast', 'eggs', '🌿', 8, 'quick', 412, 24, 35, 19, 5, 6, 628, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"pesto","amount":15,"unit":"ml"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Warm the pesto in a pan over medium heat until it sizzles","Crack in the eggs and fry them for 3 minutes until the whites are set, spooning the pesto over them","Toast the bread, slice the tomato and lay it on the toast","Top with the eggs and season with black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","eggs","pesto","bread","tomato","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, '{"bg":{"name":"Яйца с песто върху препечен хляб","description":"Яйца, изпържени в песто, върху филийка с пресен домат","instructions":["Затоплете пестото в тиган на среден огън, докато зацвърчи","Чукнете яйцата и ги пържете 3 минути, докато белтъкът стегне, като ги поливате с пестото","Препечете хляба, нарежете домата на резенчета и го наредете върху филийките","Сложете яйцата отгоре и поръсете с черен пипер"],"seasonings":["черен пипер"]},"nl":{"name":"Pesto-eieren op toast","description":"Eieren gebakken in pesto, op toast met verse tomaat","instructions":["Verwarm de pesto in een pan op middelhoog vuur tot hij sist","Breek de eieren erin en bak ze 3 minuten tot het eiwit gestold is; schep de pesto erover","Rooster het brood, snijd de tomaat in plakjes en leg ze op de toast","Leg de eieren erop en bestrooi met zwarte peper"],"seasonings":["zwarte peper"]}}'::jsonb, 57),
  ('b-tomato-chickpea-bruschetta', 'Tomato and Chickpea Bruschetta', 'Garlic-rubbed toast piled with tomato and chickpeas in olive oil', 'breakfast', 'chickpeas', '🥖', 8, 'quick', 414, 17, 58, 14, 12, 10, 571, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["pinch of salt","black pepper","pinch of dried oregano"]'::jsonb, '["Dice the tomato and mix it with the drained chickpeas, the olive oil, a pinch of salt and black pepper, lightly crushing some of the chickpeas with a fork","Toast the bread and rub it with the cut side of the halved garlic","Pile the tomato and chickpeas on the toast and finish with a pinch of dried oregano"]'::jsonb, '[]'::jsonb, '["italian","fresh","quick","bread","chickpeas","tomato","olive oil","garlic","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Брускета с домат и нахут","description":"Натрита с чесън препечена филийка с домат и нахут в зехтин","instructions":["Нарежете домата на кубчета и го смесете с отцедения нахут, зехтина, щипка сол и черен пипер, като леко намачкате част от нахута с вилица","Препечете хляба и го натрийте с разрязаната страна на скилидката чесън","Сложете домата и нахута върху филийките и поръсете с щипка сух риган"],"seasonings":["щипка сол","черен пипер","щипка сух риган"]},"nl":{"name":"Bruschetta met tomaat en kikkererwten","description":"Toast ingewreven met knoflook, met tomaat en kikkererwten in olijfolie","instructions":["Snijd de tomaat in blokjes en meng hem met de uitgelekte kikkererwten, de olijfolie, een snufje zout en zwarte peper; plet een paar kikkererwten licht met een vork","Rooster het brood en wrijf het in met de snijkant van de gehalveerde knoflook","Schep de tomaat en de kikkererwten op de toast en maak af met een snufje gedroogde oregano"],"seasonings":["snufje zout","zwarte peper","snufje gedroogde oregano"]}}'::jsonb, 58),
  ('b-soft-egg-bruschetta', 'Bruschetta with Soft Eggs', 'Tomato bruschetta topped with soft-boiled eggs', 'breakfast', 'eggs', '🥚', 12, 'quick', 437, 24, 38, 21, 6, 7, 483, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"tomato","amount":150,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["pinch of salt","black pepper"]'::jsonb, '["Boil the eggs for 6 minutes, cool them under cold water and peel them","Dice the tomato and toss it with the olive oil, salt and black pepper","Toast the bread, rub it with the cut side of the halved garlic and spoon the tomato on top","Halve the eggs and lay them on the bruschetta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","bread","eggs","tomato","olive oil","garlic","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Брускета с рохки яйца","description":"Брускета с домати и рохко сварени яйца отгоре","instructions":["Сварете яйцата за 6 минути, охладете ги под студена вода и ги обелете","Нарежете домата на кубчета и го разбъркайте със зехтина, сол и черен пипер","Препечете хляба, натрийте го с разрязаната страна на скилидката чесън и сложете домата отгоре","Разрежете яйцата наполовина и ги наредете върху брускетата"],"seasonings":["щипка сол","черен пипер"]},"nl":{"name":"Bruschetta met zachtgekookte eieren","description":"Tomatenbruschetta met zachtgekookte eieren erop","instructions":["Kook de eieren 6 minuten, laat ze schrikken onder koud water en pel ze","Snijd de tomaat in blokjes en meng hem met de olijfolie, zout en zwarte peper","Rooster het brood, wrijf het in met de snijkant van de gehalveerde knoflook en schep de tomaat erop","Halveer de eieren en leg ze op de bruschetta"],"seasonings":["snufje zout","zwarte peper"]}}'::jsonb, 59)
